syntax:
expression = operand { operator operand } ;
// with operator precedence and associativity rules determining evaluation order
// e.g., 'a + b * c' is parsed as 'a + (b * c)' due to higher precedence of '*'

code_example:
int result = *ptr + (func() ? 1 : 0) * value;
// Demonstrates complex expression with pointer dereference, conditional operator, and multiplication
int *p = &a; // pointer declaration
int a = 10, b = 20, c = 30;
int *ptr = &a;
int result = *ptr + (func() ? 1 : 0) * b;
// 'func()' is a function call; the expression combines pointer dereference, conditional, and multiplication
int *p1, *p2; // multiple pointer declarations with complex expressions
p1 = p2 = &a; // chained assignment with pointers
